import{_ as s,C as c,o as t,c as r,a2 as d,b as i,w as o,a as l,E as n,a3 as p}from"./chunks/framework.BaXgE4DV.js";const k=JSON.parse('{"title":"보안 규칙","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/security-rules.md","filePath":"architecture/security-rules.md","lastUpdated":1791550325000}'),u={name:"architecture/security-rules.md"};function h(g,e,b,m,f,C){const a=c("Mermaid");return t(),r("div",null,[e[1]||(e[1]=d(`<h1 id="보안-규칙" tabindex="-1">보안 규칙 <a class="header-anchor" href="#보안-규칙" aria-label="Permalink to &quot;보안 규칙&quot;">​</a></h1><p><code>firestore.rules</code>와 <code>storage.rules</code>가 클라이언트가 할 수 있는 일의 전부를 정합니다. 이 문서는 규칙의 설계 원칙과 이유를 설명합니다. 컬렉션별 필드는 <a href="/grato-docs/architecture/data-model">데이터 모델</a>을 보세요.</p><h2 id="신뢰-모델" tabindex="-1">신뢰 모델 <a class="header-anchor" href="#신뢰-모델" aria-label="Permalink to &quot;신뢰 모델&quot;">​</a></h2><table tabindex="0"><thead><tr><th>원칙</th><th>내용</th></tr></thead><tbody><tr><td>기본 거부</td><td>규칙에 없는 경로는 모두 거부됩니다.</td></tr><tr><td>멤버십은 서버만</td><td><code>groups.memberIds</code>, <code>users.groupIds</code>, <code>inviteCodes</code>는 Circle callable(Admin SDK)만 씁니다.</td></tr><tr><td>서버 계산 데이터</td><td><code>userStats</code>, <code>userBadges</code>, <code>gratitudes.commentCount</code>, 글·댓글의 <code>moderation</code>(숨김)은 함수만 씁니다.</td></tr><tr><td>신원의 원본은 <code>publicProfiles</code></td><td>글·댓글의 작성자 필드는 <code>publicProfiles/{uid}</code>와 같아야 합니다.</td></tr><tr><td>공개 이름은 유일</td><td><code>publicNames/{sha256(publicName)}</code> 선점을 가진 사람만 그 이름을 씁니다.</td></tr><tr><td>문서 ID는 자동 ID</td><td>클라이언트가 만드는 글·댓글·신고 ID는 영숫자 20자여야 합니다. 서버가 그 ID로 만드는 마커·시스템 신고 ID를 미리 차지할 수 없습니다.</td></tr><tr><td>외부 공유는 opt-in</td><td>공유 페이지는 작성자가 공개한 것만 보여 줍니다(서버가 판단).</td></tr><tr><td>질문은 서버만 씀</td><td><code>questions</code>의 모든 쓰기는 <code>submitQuestion</code>·<code>reviewQuestion</code> callable과 시드 스크립트만 합니다(운영자도 직접 쓰지 않음).</td></tr><tr><td>글을 쓰려면 약관 동의</td><td>감사 글·댓글 생성은 <code>users/{uid}.consent</code>가 있어야 합니다. 동의 화면을 건너뛰어도 소용없습니다. → <a href="#consent">약관 동의</a></td></tr><tr><td>삭제·정지 직후 쓰기 차단</td><td><code>disabledUsers/{uid}</code>가 유효한 동안 그 계정의 모든 생성 경로를 거부합니다. → <a href="#active-user">아래</a></td></tr><tr><td>&quot;나만 보기&quot;는 운영자에게도 비공개</td><td>운영자는 다른 사람이 볼 수 있는 글(Circle, 링크 공개)과 그 댓글만 읽습니다. → <a href="#safety">신고·차단·숨김</a></td></tr></tbody></table><h2 id="멤버십은-callable로만" tabindex="-1">멤버십은 callable로만 <a class="header-anchor" href="#멤버십은-callable로만" aria-label="Permalink to &quot;멤버십은 callable로만&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>groups:      create, delete → 거부 / update → 관리자의 name·description·photoURL만</span></span>
<span class="line"><span>             get → 멤버, 또는 운영자(신고된 Circle 확인, list는 불가)</span></span>
<span class="line"><span>inviteCodes: get만 (list·쓰기 거부)</span></span>
<span class="line"><span>users:       groupIds·isAdmin 변경 거부, 생성 시 groupIds는 빈 배열만, delete 거부</span></span></code></pre></div><p><strong>이유.</strong> 초대 코드로 참여하려면 &quot;코드가 존재하고 만료되지 않았으며 사용 횟수와 정원이 남았고, 내보낸 사용자가 아니며, 사용자의 Circle 수가 한도 아래&quot;를 한 번에 확인하고 <code>groups</code>·<code>users</code>·<code>inviteCodes</code> 세 문서를 원자적으로 바꿔야 합니다. 규칙만으로는 이 검증과 원자성을 보장하기 어려워, 멤버십 변경은 트랜잭션을 쓰는 callable 함수로 옮겼습니다. → <a href="/grato-docs/features/circles">Circle</a>, <a href="/grato-docs/decisions#adr-3">결정 기록 #3</a></p><h2 id="작성자-필드-검증" tabindex="-1">작성자 필드 검증 <a class="header-anchor" href="#작성자-필드-검증" aria-label="Permalink to &quot;작성자 필드 검증&quot;">​</a></h2><p>글(<code>gratitudes</code>)과 댓글을 만들 때 규칙이 <code>publicProfiles/{auth.uid}</code>를 읽어 다음을 비교합니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>authorName       == profile.displayName</span></span>
<span class="line"><span>authorTag        == profile.tag</span></span>
<span class="line"><span>authorPublicName == profile.publicName</span></span>
<span class="line"><span>authorPhotoURL   == profile.photoURL (없으면 null)</span></span></code></pre></div><p>작성자 정보를 글에 복사해 두는 이유는 피드를 그릴 때 작성자마다 프로필을 다시 읽지 않기 위해서입니다(비정규화). 복사본이 원본과 같다는 것을 생성 시점에 규칙이 보장합니다. 클라이언트는 쓰기 직전에 항상 프로필을 다시 읽습니다(<code>getAuthorFields</code>).</p><h2 id="공개-프로필과-이름의-유일성" tabindex="-1">공개 프로필과 이름의 유일성 <a class="header-anchor" href="#공개-프로필과-이름의-유일성" aria-label="Permalink to &quot;공개 프로필과 이름의 유일성&quot;">​</a></h2><ul><li><code>publicProfiles</code>는 <code>{displayName, tag, publicName, photoURL}</code> 4개 필드만, <code>publicName == displayName + &quot; #&quot; + tag</code>.</li><li><code>tag</code>는 한 번 정해지면 바뀌지 않습니다.</li><li><code>photoURL</code>은 본인 Storage 경로(<code>profilePhotos/{uid}/…</code>)이거나, ID 토큰의 <code>picture</code> 클레임과 같은 Google 아바타 URL이어야 합니다. 다른 사람의 사진이나 임의의 외부 URL은 쓸 수 없습니다.</li><li>프로필은 <strong>get만</strong> 허용합니다. 목록 조회를 막아 사용자 목록을 통째로 가져갈 수 없게 합니다.</li></ul><p><code>publicName</code>이 유일하도록 <code>publicNames/{key}</code> 선점 문서를 씁니다.</p>`,14)),(t(),i(p,null,{default:o(()=>[n(a,{id:"mermaid-156",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%EC%9D%B4%EB%A6%84%20%EB%B3%80%EA%B2%BD%20%EB%B0%B0%EC%B9%98%22%5D%20--%3E%20B%5B%22publicProfiles%2F%7Buid%7D%3Cbr%2F%3EpublicName%20%3D%20%EC%83%88%20%EC%9D%B4%EB%A6%84%22%5D%0A%20%20A%20--%3E%20C%5B%22publicNames%2F%7Bsha256(%EC%83%88%20%EC%9D%B4%EB%A6%84)%7D%3Cbr%2F%3Euid%20%3D%20%EB%82%98%20(%EC%83%9D%EC%84%B1%EB%A7%8C%20%EA%B0%80%EB%8A%A5)%22%5D%0A%20%20A%20--%3E%20D%5B%22publicNames%2F%7Bsha256(%EC%98%9B%20%EC%9D%B4%EB%A6%84)%7D%3Cbr%2F%3E%EC%82%AD%EC%A0%9C%22%5D%0A%20%20B%20-.-%3E%7CgetAfter%EB%A1%9C%20%ED%99%95%EC%9D%B8%7C%20C%0A%20%20C%20-.-%3E%7CgetAfter%EB%A1%9C%20%ED%99%95%EC%9D%B8%7C%20B%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=d(`<ul><li>선점 문서는 <strong>생성만</strong> 가능하고 덮어쓸 수 없습니다. 먼저 만든 사람이 이름을 가집니다.</li><li>선점은 &quot;같은 배치가 끝난 뒤 내 프로필이 그 이름을 갖는 경우&quot;에만 만들 수 있습니다(<code>getAfter</code>). 쓰지도 않는 이름을 미리 차지할 수 없습니다.</li><li>이름을 바꿀 때 예전 이름의 선점은 같은 배치에서 지워야 합니다.</li><li>선점 제도 이전 사용자의 이름은 배포 전후에 <code>backfillPublicNames</code>로 선점을 만들어 둡니다. → <a href="/grato-docs/operations/deploy">배포</a></li></ul><h2 id="consent" tabindex="-1">약관 동의 <a class="header-anchor" href="#consent" aria-label="Permalink to &quot;약관 동의 {#consent}&quot;">​</a></h2><p><code>users/{uid}.consent</code>는 약관 동의와 만 14세 이상 확인 기록입니다. → <a href="/grato-docs/features/account#consent">약관 동의와 연령 확인</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>users.consent: 정확히 { termsVersion: 1~32자 문자열, ageConfirmed: true, at: request.time }</span></span>
<span class="line"><span>               생성 때 또는 수정 때 통째로 씀 (새 버전 동의 = 다시 씀)</span></span>
<span class="line"><span>               지우거나 일부만 바꾸는 수정 → 거부</span></span>
<span class="line"><span>gratitudes, comments create: get(users/{auth.uid}).data.consent is map  (hasConsent)</span></span></code></pre></div><ul><li>동의 화면은 클라이언트 화면이라 건너뛸 수 있으므로, 규칙이 UGC(글·댓글)를 만들 때 동의 기록을 직접 확인합니다.</li><li>규칙은 <strong>기록이 있는지</strong>만 봅니다. 현재 버전인지는 클라이언트가 판단해 다시 묻습니다. 약관 버전을 올릴 때 규칙을 다시 배포하지 않아도 되게 하기 위해서입니다.</li><li><code>users</code> 문서가 없으면 <code>get()</code>이 실패해 거부됩니다. 새 사용자의 첫 글은 로그인 동기화(<code>users</code> 생성)를 기다립니다.</li></ul><h2 id="active-user" tabindex="-1">삭제·정지 직후의 쓰기 차단 <a class="header-anchor" href="#active-user" aria-label="Permalink to &quot;삭제·정지 직후의 쓰기 차단 {#active-user}&quot;">​</a></h2><p>Firebase Auth 사용자를 지우거나 정지해도, 이미 발급된 ID 토큰은 최대 1시간 동안 규칙과 callable을 통과합니다. 그래서 서버가 계정 삭제·이용 정지 직후에 서버 전용 문서 <code>disabledUsers/{uid}</code>(<code>expireAt</code> 2시간 뒤)를 쓰고, 규칙은 모든 <strong>생성 경로</strong>에서 이를 확인합니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>isActiveUser() = !exists(disabledUsers/{auth.uid}) || get(…).data.expireAt &lt; request.time</span></span></code></pre></div><table tabindex="0"><thead><tr><th>확인하는 곳</th><th></th></tr></thead><tbody><tr><td><code>users</code> 생성·수정, <code>publicProfiles</code> 생성·수정, <code>publicShares</code> 쓰기</td><td>삭제한 계정이 문서를 되살리지 못하게</td></tr><tr><td><code>gratitudes</code>, <code>comments</code>, <code>reports</code>, <code>feedback</code>, <code>analyticsEvents</code> 생성</td><td>정지한 계정이 계속 쓰지 못하게</td></tr><tr><td><code>users/{uid}/blocks</code>, <code>pushTokens</code> 생성·수정</td><td>남은 데이터가 생기지 않게</td></tr></tbody></table><ul><li>비용을 줄이려고 형태 검사 같은 싼 조건 뒤에 둡니다. 교차 읽기는 1번(있으면 같은 문서 get 포함 2번)입니다.</li><li>callable도 같은 문서를 확인합니다(<code>requireActiveUser</code>: <code>createCircle</code>, <code>joinCircle</code>, <code>submitQuestion</code>). → <a href="/grato-docs/architecture/cloud-functions#safety">Cloud Functions</a></li><li>읽기와 삭제(차단 해제, 토큰 삭제)는 막지 않습니다.</li></ul><h2 id="get-list" tabindex="-1">감사 글: get과 list 분리 <a class="header-anchor" href="#get-list" aria-label="Permalink to &quot;감사 글: get과 list 분리 {#get-list}&quot;">​</a></h2><p>Firestore는 단건 읽기(<code>get</code>)와 쿼리(<code>list</code>)를 다르게 평가합니다.</p><table tabindex="0"><thead><tr><th></th><th><code>get</code></th><th><code>list</code></th></tr></thead><tbody><tr><td>평가 방식</td><td>실제 문서(<code>resource.data</code>)로 판단</td><td>쿼리가 돌려줄 <strong>수 있는</strong> 모든 문서가 규칙을 통과해야 함</td></tr><tr><td>허용 조건</td><td>작성자이거나, 숨기지 않은 글이면 <code>groupId</code>의 현재 멤버, 또는 운영자(다른 사람이 볼 수 있는 글만)</td><td>쿼리 조건이 작성자 또는 멤버 조건을 보장해야 함</td></tr></tbody></table><p>허용되는 쿼리 형태:</p><table tabindex="0"><thead><tr><th>쿼리</th><th>쓰는 곳</th><th>교차 읽기</th></tr></thead><tbody><tr><td><code>where(&#39;userId&#39;, &#39;==&#39;, 내 uid)</code> [+ <code>createdAt</code> 범위·정렬, <code>startAfter</code>]</td><td>홈 &quot;내 기록&quot; 탭(실시간 첫 20개 + 더 보기), MyPage, 캘린더</td><td>0</td></tr><tr><td><code>where(&#39;groupId&#39;, &#39;==&#39;, X)</code> [+ <code>createdAt</code> 범위] + <code>orderBy(&#39;createdAt&#39;)</code> (X의 멤버)</td><td>Circle 피드, 오늘의 활동</td><td>1 (요청당 캐시)</td></tr></tbody></table><p>필터 없는 조회, 다른 사람의 <code>userId</code>, 내가 속하지 않은 <code>groupId</code>, 그리고 <code>groupId in [...]</code>는 거부됩니다. <code>in</code> 쿼리를 막는 이유는 그룹마다 <code>get()</code>이 하나씩 필요해 <a href="#get-budget">교차 읽기 한도</a>를 넘을 수 있기 때문입니다. 그래서 클라이언트는 그룹마다 쿼리를 따로 보냅니다(다중 그룹 통합 피드는 아직 없음).</p><p>작성자 조건을 먼저 검사하므로, 작성자는 Circle을 떠나거나 Circle이 삭제된 뒤에도, 글이 숨겨진 동안에도 자기 글을 읽을 수 있습니다. → <a href="/grato-docs/decisions#adr-2">결정 기록 #2</a>, <a href="/grato-docs/decisions#adr-4">#4</a></p><p>숨김(<code>moderation.status == &quot;hidden&quot;</code>)은 <code>get</code>에서만 규칙으로 판단합니다. 쿼리는 숨김 여부를 조건으로 표현할 수 없기 때문입니다(필드가 없는 예전 문서가 부등호 필터에서 빠짐). 대신 숨긴 Circle 글은 서버가 <code>groupId</code>를 비워 Circle 피드 쿼리에서 빠지게 하고, 목록에 보일지는 클라이언트(<code>canSeeItem</code>)가 한 번 더 정합니다. → <a href="/grato-docs/features/safety#auto-moderation">자동 숨김</a></p><h2 id="감사-글-생성과-수정" tabindex="-1">감사 글: 생성과 수정 <a class="header-anchor" href="#감사-글-생성과-수정" aria-label="Permalink to &quot;감사 글: 생성과 수정&quot;">​</a></h2><p><strong>생성</strong> — 단일 <code>setDoc</code>, 자동 ID, 정해진 11개 필드만. 기본은 개인 글(<code>groupId: null</code>)이고, Circle 공유는 작성자가 고른 경우에만 <code>groupId</code>가 들어갑니다(규칙은 둘 다 허용하고, 기본값은 클라이언트가 정함 → <a href="/grato-docs/features/gratitudes#visibility">공개 범위</a>):</p><ul><li><code>userId == auth.uid</code>, <code>groupId</code>가 있으면 현재 멤버</li><li><code>title</code> 0~100자, <code>content</code> 1~3000자 (바이트가 아니라 글자 수)</li><li>작성자 필드 == 공개 프로필</li><li><code>reactions</code>는 4개 이모지의 빈 배열, <code>isPublic == false</code>, <code>createdAt == request.time</code></li><li>약관 동의 기록이 있고(<code>hasConsent</code>), 계정이 잠겨 있지 않음(<code>isActiveUser</code>)</li><li><code>moderation</code> 필드는 만들 수 없음(정해진 필드 목록에 없음)</li></ul><p><strong>수정</strong> — 정확히 두 가지 형태만 허용합니다.</p><table tabindex="0"><thead><tr><th>형태</th><th>누가</th><th>바뀌는 필드</th><th>조건</th></tr></thead><tbody><tr><td>리액션 토글</td><td>글을 읽을 수 있는 사람</td><td><code>reactions</code></td><td>이모지는 ❤️ 🙏 ✨ 🔥 중 하나, 바뀐 것은 <strong>본인 uid의 추가·제거뿐</strong>, 배열 중복 없음</td></tr><tr><td>공개 전환</td><td>작성자</td><td><code>isPublic</code>, <code>sharedAt</code></td><td><code>isPublic</code>은 bool, <code>sharedAt</code>은 null 또는 이번 요청의 서버 시간. <strong>숨긴 글은 공개로 바꿀 수 없음</strong>(비공개로는 가능)</td></tr></tbody></table><p>리액션과 다른 필드를 함께 바꾸는 요청, <code>commentCount</code>·<code>moderation</code> 변경, 내용·작성자·그룹 변경은 모두 거부됩니다. 예전 문서의 다른 이모지 키는 그대로 둘 수 있지만 수정할 수는 없습니다. 운영자의 리액션·댓글 권한은 늘어나지 않습니다(운영자 읽기는 <code>get</code>에만 따로 붙임).</p><p><strong>삭제</strong> — <strong>작성자만</strong> 지울 수 있습니다. 댓글 하위 컬렉션과 통계는 <code>onGratitudeDeleted</code> 트리거가 정리합니다(규칙은 하위 컬렉션을 지우지 않음). → <a href="/grato-docs/features/gratitudes#delete">감사 글 삭제</a></p><h2 id="댓글" tabindex="-1">댓글 <a class="header-anchor" href="#댓글" aria-label="Permalink to &quot;댓글&quot;">​</a></h2><table tabindex="0"><thead><tr><th>동작</th><th>조건</th></tr></thead><tbody><tr><td>get</td><td>부모 글을 읽을 수 있는 사람 (숨긴 댓글은 그 작성자만), 또는 운영자 (다른 사람이 볼 수 있는 글의 댓글만)</td></tr><tr><td>list</td><td>부모 글을 읽을 수 있는 사람, 또는 운영자 (같은 조건). 숨긴 댓글은 클라이언트가 작성자 외에는 거름</td></tr><tr><td>생성</td><td>부모 글을 읽을 수 있음 + 자동 ID + 7개 필드 + 작성자 필드 == 공개 프로필 + <code>content</code> 1~500자 + 약관 동의 + 활성 계정</td></tr><tr><td>삭제</td><td>댓글 작성자 또는 부모 글 작성자</td></tr><tr><td>수정</td><td>불가 (<code>moderation</code>은 서버만)</td></tr></tbody></table><p>댓글 생성은 규칙에서 교차 읽기를 5번(부모 글, 그 그룹, 공개 프로필, <code>users</code>, 잠금 문서) 하는, 가장 비싼 단일 요청입니다.</p><h2 id="외부-공유-opt-in" tabindex="-1">외부 공유 opt-in <a class="header-anchor" href="#외부-공유-opt-in" aria-label="Permalink to &quot;외부 공유 opt-in&quot;">​</a></h2><p>공유 페이지는 Admin SDK를 쓰는 <code>shareRenderer</code>가 렌더링하므로, 공개 여부는 규칙이 아니라 서버 코드가 판단합니다. 규칙은 그 판단의 입력을 지킵니다.</p><ul><li>감사 글: <code>isPublic</code>·<code>sharedAt</code>은 작성자만 바꿀 수 있습니다.</li><li>캘린더 월·배지: <code>publicShares/{uid}</code>는 본인만 읽고 씁니다. <code>calendarMonths</code>(최대 120), <code>badgeIds</code>(최대 200) 두 목록만 허용합니다.</li></ul><p>로그인하지 않은 사람은 Firestore에서 글을 직접 읽을 수 없습니다. 공유 페이지의 내용은 서버가 HTML에 넣어 준 것만 보입니다. 숨긴 글은 공개 상태여도 서버가 &quot;비공개&quot;로 보여 줍니다. → <a href="/grato-docs/features/gratitudes#sharing">감사 글과 공유</a></p><h2 id="safety" tabindex="-1">신고·차단·숨김 <a class="header-anchor" href="#safety" aria-label="Permalink to &quot;신고·차단·숨김 {#safety}&quot;">​</a></h2><p>기능 설명은 <a href="/grato-docs/features/safety">신고·차단과 자동 숨김</a>에 있습니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reports:            create → 로그인 사용자가 자기 이름으로, 자동 ID, 정해진 형태, 활성 계정</span></span>
<span class="line"><span>                    read   → 운영자만 (get, list) — 신고한 본인도 읽을 수 없음</span></span>
<span class="line"><span>                    update, delete → 거부 (상태 변경·익명화는 서버)</span></span>
<span class="line"><span>users/{uid}/blocks: read, delete → 본인</span></span>
<span class="line"><span>                    create, update → 본인, { createdAt: request.time }만, 자기 자신 차단 불가, 활성 계정</span></span>
<span class="line"><span>disabledUsers:      읽기·쓰기 모두 거부</span></span></code></pre></div><p>신고 생성 형태(<code>isValidNewReport</code>):</p><ul><li>필드는 <code>reporterId</code>, <code>targetType</code>, <code>targetId</code>, <code>parentId</code>, <code>reason</code>, <code>detail</code>, <code>status</code>, <code>createdAt</code>만. <code>reporterId == auth.uid</code>, <code>status == &quot;open&quot;</code>, <code>createdAt == request.time</code></li><li><code>targetType</code>은 5종, <code>reason</code>은 7종 중 하나. ID 값은 <code>[A-Za-z0-9_-]</code> 1~128자(운영자 화면이 이 값으로 문서 경로를 만들기 때문)</li><li>댓글 신고는 <code>parentId</code>(부모 글)가 필수, 그 밖은 없거나 null. 자기 자신을 사용자로 신고할 수 없음</li><li><code>detail</code>은 없음·null·500자 이하 문자열</li><li>대상 문서를 규칙에서 읽지 않습니다. 교차 읽기를 줄이고, 더 이상 읽을 수 없게 된 대상(나간 Circle의 글 등)도 신고할 수 있게 하기 위해서입니다. 대상 정보는 <code>onReportCreated</code>가 채웁니다.</li><li>규칙은 개수를 셀 수 없어 도배는 서버가 처리합니다(24시간에 20개 초과 → <code>spam</code>).</li></ul><p>운영자 읽기는 다른 사람이 볼 수 있는 글로 한정합니다(<code>hasAudience</code>: <code>groupId</code>가 있거나, 숨겨져 <code>moderation.groupId</code>에 Circle이 있거나, <code>isPublic</code>). 신고된 콘텐츠를 판단하는 데 필요한 만큼만 열고, &quot;나만 보기&quot; 글과 그 댓글은 운영자도 읽을 수 없습니다. <code>isAdmin()</code> 확인은 항상 마지막에 둬서 일반 사용자의 읽기에는 교차 읽기가 늘지 않습니다.</p><h2 id="questions" tabindex="-1">질문 제안 <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;질문 제안 {#questions}&quot;">​</a></h2><p>제안한 질문은 <strong>사전 검토</strong>를 거칩니다. 운영자가 선정하기 전에는 제안자 본인과 운영자만 읽을 수 있고, 선정된 질문만 다른 사용자에게 보입니다. 클라이언트 쓰기는 운영자를 포함해 모두 거부하고, 검증·한도·상태 변경은 callable이 합니다. → <a href="/grato-docs/features/questions">질문 제안과 선정</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>questions:         read  → 로그인 사용자이고</span></span>
<span class="line"><span>                            status == &#39;approved&#39;  (누구나: 질문으로 쓰기)</span></span>
<span class="line"><span>                            || authorId == auth.uid (제안자: 모든 상태)</span></span>
<span class="line"><span>                            || isAdmin()            (운영자: 검토 대기열)</span></span>
<span class="line"><span>                   write → 모두 거부 (운영자도 callable로만)</span></span>
<span class="line"><span>questionOriginals: read  → 운영자만 / write → 거부</span></span></code></pre></div><p>허용되는 쿼리 형태:</p><table tabindex="0"><thead><tr><th>쿼리</th><th>쓰는 곳</th></tr></thead><tbody><tr><td><code>where(&#39;status&#39;, &#39;==&#39;, &#39;approved&#39;)</code> [+ <code>kind</code>, <code>limit</code>]</td><td>질문으로 쓰기 (누구나)</td></tr><tr><td><code>where(&#39;authorId&#39;, &#39;==&#39;, 내 uid)</code> + <code>orderBy(&#39;createdAt&#39;, &#39;desc&#39;)</code></td><td>MyPage 내가 제안한 질문</td></tr><tr><td><code>where(&#39;status&#39;, &#39;==&#39;, X)</code> [+ <code>orderBy(&#39;createdAt&#39;)</code>], 상태별 개수</td><td>운영자 검토 화면</td></tr></tbody></table><ul><li><code>gratitudes</code>와 달리 get과 list를 나누지 않습니다. 세 분기 모두 쿼리 조건(<code>status ==</code>, <code>authorId ==</code>)이나 요청자(<code>isAdmin()</code>)만으로 판단할 수 있어 하나의 <code>read</code> 규칙으로 정확히 표현됩니다.</li><li>다른 사람의 검토 중·반려·숨김 질문, 상태를 섞은 쿼리, 필터 없는 조회는 운영자가 아니면 거부됩니다. 로그인하지 않은 사람은 선정된 질문도 읽을 수 없습니다.</li><li>운영자 확인(<code>isAdmin()</code>)을 마지막에 두어, 선정된 질문과 본인 질문을 읽을 때는 교차 읽기가 생기지 않습니다.</li><li><strong>선정된 질문 문서는 필드 단위로 숨길 수 없습니다.</strong> 그래서 검토한 운영자의 uid는 <code>adminAuditLogs</code>에, 운영자가 고치기 전 제안 원문은 <code>questionOriginals</code>에 두고, 질문 문서에는 공개해도 되는 값만 둡니다. <code>authorId</code>는 uid이지만 공개 프로필과 함께 이미 공개되는 값입니다.</li></ul><h2 id="서버-전용-컬렉션" tabindex="-1">서버 전용 컬렉션 <a class="header-anchor" href="#서버-전용-컬렉션" aria-label="Permalink to &quot;서버 전용 컬렉션&quot;">​</a></h2><table tabindex="0"><thead><tr><th>컬렉션</th><th>클라이언트</th></tr></thead><tbody><tr><td><code>userStats</code>, <code>userBadges</code></td><td>본인 읽기만</td></tr><tr><td><code>notificationLogs</code>, <code>statsLogs</code>, <code>questionQuota</code>, <code>adminAuditLogs</code>, <code>disabledUsers</code></td><td>읽기·쓰기 모두 거부 (운영자도)</td></tr><tr><td><code>questionOriginals</code></td><td>운영자만 읽기, 쓰기 거부</td></tr><tr><td><code>reports</code></td><td>본인 이름으로 생성만, 운영자만 읽기, 수정·삭제 거부</td></tr><tr><td>예전 AI 글쓰기 컬렉션</td><td><code>match</code> 블록 없음 → 기본 거부 (본인 기록도 읽기·쓰기 불가)</td></tr><tr><td><code>badges</code></td><td>로그인 사용자 읽기, <code>isAdmin</code> 사용자만 쓰기</td></tr><tr><td><code>feedback</code></td><td>본인 생성(최대 2000자), 본인·관리자 읽기</td></tr><tr><td><code>analyticsEvents</code></td><td>본인 uid로 생성(이벤트명 64자, <code>createdAt</code>은 서버 시간), 관리자만 읽기</td></tr></tbody></table><p>관리자 여부는 <code>users/{uid}.isAdmin</code>으로 판단하며, 이 필드는 클라이언트가 만들거나 바꿀 수 없습니다(콘솔 또는 Admin SDK로만 설정).</p><h2 id="storage" tabindex="-1">Storage 규칙 <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage 규칙 {#storage}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>경로</th><th>읽기</th><th>쓰기</th></tr></thead><tbody><tr><td><code>profilePhotos/{uid}/{file}</code></td><td>누구나</td><td>본인, 이미지, 5MB 미만</td></tr><tr><td><code>circlePhotos/{groupId}/{file}</code></td><td>누구나</td><td><strong>그 Circle의 관리자</strong>, 이미지, 5MB 미만</td></tr><tr><td>그 밖의 경로</td><td>거부</td><td>거부</td></tr></tbody></table><p>클라이언트는 올리기 전에 사진을 <strong>긴 변 512px JPEG</strong>로 줄이고(<code>src/lib/imageResize.js</code>, 원본은 10MB까지 받음), <code>Cache-Control: public, max-age=31536000, immutable</code>을 붙여 올립니다. 경로에 시각이 들어가 파일이 바뀌지 않으므로 기기·브라우저가 1년 동안 다시 받지 않습니다(Storage 기본값은 <code>private, max-age=0</code>이라 볼 때마다 다시 확인했음).</p><p><code>circlePhotos</code>는 <strong>서비스 간(cross-service) 규칙</strong>입니다. Storage 규칙이 <code>firestore.get()</code>으로 <code>groups/{groupId}.adminId</code>를 읽어 관리자인지 확인합니다. Circle 문서가 없으면 실패(거부)합니다.</p><div class="warning custom-block"><p class="custom-block-title">첫 배포 시 권한 부여</p><p>cross-service 규칙이 동작하려면 Storage 규칙 서비스 에이전트가 Firestore를 읽을 권한이 있어야 합니다. <code>firebase deploy --only storage</code>가 처음에 권한 부여를 묻습니다. → <a href="/grato-docs/operations/deploy#prompts">배포</a></p></div><h2 id="get-budget" tabindex="-1">교차 문서 읽기 예산 <a class="header-anchor" href="#get-budget" aria-label="Permalink to &quot;교차 문서 읽기 예산 {#get-budget}&quot;">​</a></h2><p>Firestore 규칙은 요청 하나당 <code>get()</code>/<code>exists()</code>를 <strong>10번</strong>(배치·트랜잭션은 20번)까지 허용합니다. 같은 문서를 다시 읽는 것은 캐시되어 한 번으로 셉니다.</p><table tabindex="0"><thead><tr><th>요청</th><th>교차 읽기</th></tr></thead><tbody><tr><td>내 글 목록 조회</td><td>0</td></tr><tr><td>Circle 피드 조회</td><td>1 (그룹)</td></tr><tr><td>글 생성 (Circle 글)</td><td>4 (그룹 + 공개 프로필 + <code>users</code>의 동의 + 잠금 문서)</td></tr><tr><td>리액션 토글 (Circle 글)</td><td>1 (그룹)</td></tr><tr><td>댓글 생성</td><td>5 (부모 글 + 그룹 + 공개 프로필 + <code>users</code> + 잠금 문서) — 단일 요청 중 최대</td></tr><tr><td>댓글 get</td><td>3 (부모 글 + 그룹 + <code>isAdmin</code>)</td></tr><tr><td>프로필 이름 변경</td><td>3 (새 선점 + 옛 선점 + 잠금 문서)</td></tr><tr><td>이름 변경 배치 전체</td><td>5 (<code>users</code> + <code>publicProfiles</code> + 선점 2개 + 잠금 문서)</td></tr><tr><td>신고 생성, 차단, <code>feedback</code>·<code>analyticsEvents</code>·푸시 토큰 생성</td><td>1 (잠금 문서)</td></tr><tr><td><code>badges</code> 쓰기, <code>reports</code> 읽기, <code>feedback</code>·<code>analyticsEvents</code> 관리자 읽기</td><td>1 (<code>users</code>의 <code>isAdmin</code>)</td></tr><tr><td>운영자의 글 get (신고 확인)</td><td>2 (그룹 + <code>isAdmin</code>)</td></tr><tr><td>선정된 질문·본인 질문 조회</td><td>0</td></tr><tr><td>운영자 질문 검토 조회, <code>questionOriginals</code> 읽기</td><td>1 (<code>users</code>의 <code>isAdmin</code>)</td></tr></tbody></table><p>새 규칙을 추가할 때는 이 표를 갱신하고 한도 안에 있는지 확인하세요. 다중 그룹 쿼리(<code>groupId in [...]</code>)를 허용하지 않는 것도 이 예산 때문입니다.</p><h2 id="규칙-테스트" tabindex="-1">규칙 테스트 <a class="header-anchor" href="#규칙-테스트" aria-label="Permalink to &quot;규칙 테스트&quot;">​</a></h2><p><code>tests/rules/</code>는 루트와 독립된 npm 패키지입니다. Firestore·Storage 에뮬레이터를 <code>demo-grato</code> 프로젝트로 띄우고 <code>@firebase/rules-unit-testing</code>으로 규칙을 검증합니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tests/rules/</span></span>
<span class="line"><span>  package.json        pretest: 루트의 규칙 파일을 .rules/로 복사</span></span>
<span class="line"><span>  firebase.json       에뮬레이터 포트 (firestore 8180, storage 9198 등)</span></span>
<span class="line"><span>  test/helpers.js     픽스처: PROFILES, seed(), gratitudeFor(), commentFor(), contexts()</span></span>
<span class="line"><span>  test/firestore.test.js</span></span>
<span class="line"><span>  test/storage.test.js</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/rules</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # JDK 21 필요 (JAVA_HOME)</span></span></code></pre></div><ul><li><code>beforeEach</code>마다 Firestore를 비우고 <code>seed()</code>로 같은 세계(사용자 alice·bob·carol·erin·root, Circle g1·g2, 예전 형식 문서 등)를 만듭니다.</li><li>컬렉션별 <code>describe</code>, 허용은 <code>assertSucceeds</code>, 거부 케이스는 이름이 <code>DENY:</code>로 시작하고 <code>assertFails</code>를 씁니다.</li><li><code>GRATO_RULES_DIR</code>로 다른 규칙 파일을 지정할 수 있습니다. 일부러 약하게 만든 규칙에서 테스트가 실패하는지 확인할 때 씁니다.</li></ul><p>테스트 추가 방법은 <a href="/grato-docs/operations/testing#add-rules-test">테스트</a>를 보세요.</p>`,62))])}const y=s(u,[["render",h]]);export{k as __pageData,y as default};
